            item_keys = item_keys | {"endpoint"}
        if not isinstance(item, dict) or set(item) != item_keys:
            fail(EXIT_INPUT, "INPUT")
        backend_id = parse_backend_id(item["id"])
        # 后端 id 须 UTF-8 可编码（建环与输出排序都会用到其字节）。
