    return ("cb", rev, parse_now(raw_op["now"]))

if name == "ts":
    if keys != {"op", "ttl"}:
        fail(EXIT_INPUT, "INPUT")
    return ("ts", parse_idle_ttl(raw_op["ttl"]))

